// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ListDevices Devices with owner, last contact and capability profile (W-7)
	// (GET /admin/devices)
	ListDevices(w http.ResponseWriter, r *http.Request)
	// DeleteDevice Forget a device
	// (DELETE /admin/devices/{id})
	DeleteDevice(w http.ResponseWriter, r *http.Request, id DeviceID)
	// ListGuests Guest accounts with their limits
	// (GET /admin/guests)
	ListGuests(w http.ResponseWriter, r *http.Request)
	// RevokeGuest Revoke a guest account (K-7)
	// (DELETE /admin/guests/{id})
	RevokeGuest(w http.ResponseWriter, r *http.Request, id AccountID)
	// UpdateGuest Change the rating ceiling or the library rights of a guest account
	// (PATCH /admin/guests/{id})
	UpdateGuest(w http.ResponseWriter, r *http.Request, id AccountID)
	// ListInvitations Invitation links with their state
	// (GET /admin/invitations)
	ListInvitations(w http.ResponseWriter, r *http.Request)
	// CreateInvitation Create a one-time invitation link (valid 7 days)
	// (POST /admin/invitations)
	CreateInvitation(w http.ResponseWriter, r *http.Request)
	// RevokeInvitation Revoke an invitation link
	// (DELETE /admin/invitations/{id})
	RevokeInvitation(w http.ResponseWriter, r *http.Request, id InvitationID)
	// SetItemsRating Assign an age rating to many titles at once (B-9, AN-1)
	// (POST /admin/items/rating)
	SetItemsRating(w http.ResponseWriter, r *http.Request)
	// GetAdminItem Administration view of a title
	// (GET /admin/items/{id})
	GetAdminItem(w http.ResponseWriter, r *http.Request, id ItemID)
	// SetItemMatch Assign a title manually to a provider entry (B-6)
	// (PUT /admin/items/{id}/match)
	SetItemMatch(w http.ResponseWriter, r *http.Request, id ItemID)
	// SetItemRating Override the age rating of a title
	// (PUT /admin/items/{id}/rating)
	SetItemRating(w http.ResponseWriter, r *http.Request, id ItemID)
	// RefreshItem Refresh metadata, images, trailers and probes of a title
	// (POST /admin/items/{id}/refresh)
	RefreshItem(w http.ResponseWriter, r *http.Request, id ItemID)
	// CreateItemTrailer Set a trailer manually (B-8 "manueller Ersatz")
	// (POST /admin/items/{id}/trailers)
	CreateItemTrailer(w http.ResponseWriter, r *http.Request, id ItemID)
	// DeleteItemTrailer Remove a trailer of a title
	// (DELETE /admin/items/{id}/trailers/{trailerId})
	DeleteItemTrailer(w http.ResponseWriter, r *http.Request, id ItemID, trailerId int64)
	// ListLibraries All libraries with their scan state
	// (GET /admin/libraries)
	ListLibraries(w http.ResponseWriter, r *http.Request)
	// CreateLibrary Create a library and start its first scan
	// (POST /admin/libraries)
	CreateLibrary(w http.ResponseWriter, r *http.Request)
	// GetLibrary One library with its scan state
	// (GET /admin/libraries/{id})
	GetLibrary(w http.ResponseWriter, r *http.Request, id LibraryID)
	// AcceptLibraryLoss Accept that files disappeared and let the next scan apply the deletions
	// (POST /admin/libraries/{id}/accept-loss)
	AcceptLibraryLoss(w http.ResponseWriter, r *http.Request, id LibraryID)
	// CancelLibraryScan Cancel the queued or running scan of a library
	// (DELETE /admin/libraries/{id}/scan)
	CancelLibraryScan(w http.ResponseWriter, r *http.Request, id LibraryID)
	// ScanLibrary Queue a full scan of the library
	// (POST /admin/libraries/{id}/scan)
	ScanLibrary(w http.ResponseWriter, r *http.Request, id LibraryID)
	// CleanupItems Remove orphaned titles and unplayable files (B-9)
	// (POST /admin/maintenance/cleanup)
	CleanupItems(w http.ResponseWriter, r *http.Request)
	// ListDuplicates Titles and files that exist twice (B-9)
	// (GET /admin/maintenance/duplicates)
	ListDuplicates(w http.ResponseWriter, r *http.Request, params ListDuplicatesParams)
	// ListMaintenanceIssues Titles and files that need attention (B-9)
	// (GET /admin/maintenance/issues)
	ListMaintenanceIssues(w http.ResponseWriter, r *http.Request, params ListMaintenanceIssuesParams)
	// MergeItems Merge duplicate titles into one (B-9)
	// (POST /admin/maintenance/merge)
	MergeItems(w http.ResponseWriter, r *http.Request)
	// SearchMetadata Search a metadata provider for the manual assignment (B-6)
	// (GET /admin/metadata/search)
	SearchMetadata(w http.ResponseWriter, r *http.Request, params SearchMetadataParams)
	// ListStreams Running playback sessions (W-6)
	// (GET /admin/streams)
	ListStreams(w http.ResponseWriter, r *http.Request)
	// StopStream End a running stream (W-6)
	// (DELETE /admin/streams/{id})
	StopStream(w http.ResponseWriter, r *http.Request, id PlaybackSessionID)
	// Login Log in with e-mail and password
	// (POST /auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// Logout End the current session
	// (POST /auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// ListMyProfiles Profiles of the signed-in account for the profile picker
	// (GET /auth/profiles)
	ListMyProfiles(w http.ResponseWriter, r *http.Request)
	// SelectProfile Activate a profile of the signed-in account (asks for its PIN)
	// (POST /auth/profiles/{id}/select)
	SelectProfile(w http.ResponseWriter, r *http.Request, id ProfileID)
	// GetSession Account and active profile of the current session
	// (GET /auth/session)
	GetSession(w http.ResponseWriter, r *http.Request)
	// DeleteDownload Delete a download (O-6)
	// (DELETE /downloads/{id})
	DeleteDownload(w http.ResponseWriter, r *http.Request, id DownloadID)
	// GetDownloadManifest Fragment index and file URL of a prepared download
	// (GET /downloads/{id}/manifest)
	GetDownloadManifest(w http.ResponseWriter, r *http.Request, id DownloadID)
	// GetHealth Liveness and readiness of the server
	// (GET /healthz)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// GetHome Rows of the start page for the active profile
	// (GET /home)
	GetHome(w http.ResponseWriter, r *http.Request)
	// GetInvitation Preview of an invitation link before accepting it
	// (GET /invitations/{token})
	GetInvitation(w http.ResponseWriter, r *http.Request, token InvitationToken)
	// AcceptInvitation Create a guest account from an invitation link
	// (POST /invitations/{token}/accept)
	AcceptInvitation(w http.ResponseWriter, r *http.Request, token InvitationToken)
	// GetItem Detail of a title
	// (GET /items/{id})
	GetItem(w http.ResponseWriter, r *http.Request, id ItemID)
	// GetDownloadOptions Download profiles of a title with size estimates (O-1)
	// (GET /items/{id}/download-options)
	GetDownloadOptions(w http.ResponseWriter, r *http.Request, id ItemID, params GetDownloadOptionsParams)
	// CreateDownloads Download a movie, an episode or a whole season to this device (O-1, O-2)
	// (POST /items/{id}/downloads)
	CreateDownloads(w http.ResponseWriter, r *http.Request, id ItemID)
	// StartPlayback Decide how the title is played and return the stream description
	// (POST /items/{id}/play)
	StartPlayback(w http.ResponseWriter, r *http.Request, id ItemID)
	// ReportProgress Report a playback progress event
	// (POST /items/{id}/progress)
	ReportProgress(w http.ResponseWriter, r *http.Request, id ItemID)
	// GetItemTracks Audio and subtitle tracks of a media file
	// (GET /items/{id}/tracks)
	GetItemTracks(w http.ResponseWriter, r *http.Request, id ItemID, params GetItemTracksParams)
	// GetItemTrailers Trailers of a title (B-8, W-10)
	// (GET /items/{id}/trailers)
	GetItemTrailers(w http.ResponseWriter, r *http.Request, id ItemID)
	// ListAccountLibraries Libraries the signed-in account may see, by name
	// (GET /libraries)
	ListAccountLibraries(w http.ResponseWriter, r *http.Request)
	// UploadOfflineEvents Upload the raw progress events of offline playback (O-5, AN-10, AN-18)
	// (POST /offline/events)
	UploadOfflineEvents(w http.ResponseWriter, r *http.Request)
	// CheckOfflineRevocations Revocation list of a device without a valid session (K-7, AN-4)
	// (POST /offline/revocations)
	CheckOfflineRevocations(w http.ResponseWriter, r *http.Request)
	// GetDownloadRules Auto-download rule of the active profile on this device (O-3)
	// (GET /offline/rules)
	GetDownloadRules(w http.ResponseWriter, r *http.Request)
	// SetDownloadRules Set the auto-download rule of the active profile on this device (O-3, AN-13)
	// (PUT /offline/rules)
	SetDownloadRules(w http.ResponseWriter, r *http.Request)
	// SyncOffline Synchronise the downloads of this device (O-6, O-7, K-7)
	// (POST /offline/sync)
	SyncOffline(w http.ResponseWriter, r *http.Request)
	// GetPerson A person with the titles the active profile may see
	// (GET /people/{id})
	GetPerson(w http.ResponseWriter, r *http.Request, id int64)
	// StopPlayback End a playback session
	// (DELETE /playback/sessions/{id})
	StopPlayback(w http.ResponseWriter, r *http.Request, id PlaybackSessionID)
	// ListProfiles Profiles of the signed-in account with their settings
	// (GET /profiles)
	ListProfiles(w http.ResponseWriter, r *http.Request)
	// CreateProfile Create a profile in the signed-in account
	// (POST /profiles)
	CreateProfile(w http.ResponseWriter, r *http.Request)
	// DeleteProfile Delete a profile with its progress
	// (DELETE /profiles/{id})
	DeleteProfile(w http.ResponseWriter, r *http.Request, id ProfileID)
	// UpdateProfile Change name, rating, language, accent or library rights of a profile
	// (PATCH /profiles/{id})
	UpdateProfile(w http.ResponseWriter, r *http.Request, id ProfileID)
	// RemoveOfflinePin Remove the separate offline PIN of a profile
	// (DELETE /profiles/{id}/offline-pin)
	RemoveOfflinePin(w http.ResponseWriter, r *http.Request, id ProfileID)
	// SetOfflinePin Set or replace the separate offline PIN of a profile (AN-19)
	// (PUT /profiles/{id}/offline-pin)
	SetOfflinePin(w http.ResponseWriter, r *http.Request, id ProfileID)
	// RemoveProfilePin Remove the PIN of a profile
	// (DELETE /profiles/{id}/pin)
	RemoveProfilePin(w http.ResponseWriter, r *http.Request, id ProfileID)
	// SetProfilePin Set or replace the PIN of a profile
	// (PUT /profiles/{id}/pin)
	SetProfilePin(w http.ResponseWriter, r *http.Request, id ProfileID)
	// GetWatchReport Watch-time report of a profile (K-5)
	// (GET /profiles/{id}/watch-time)
	GetWatchReport(w http.ResponseWriter, r *http.Request, id ProfileID, params GetWatchReportParams)
	// GetSetupStatus Whether the first-start wizard still has to run
	// (GET /setup)
	GetSetupStatus(w http.ResponseWriter, r *http.Request)
	// RunSetup Run the first-start wizard
	// (POST /setup)
	RunSetup(w http.ResponseWriter, r *http.Request)
}

